rules.cslSource:
// Desktop Auction model: role specialization follows auction_istar_final_fixed.drawio.
// auction_capabilities is an authored capability-role abstraction of the shared ASL
// program. It is not an extra MOISE role declared by auction-os.xml.
// Its attributes describe the SAME player's epistemic view, never world truth.
// The two concrete role views inherit them; no second parent-role enactment is created.
//
// Belief-view contract (generic; selected predicates belong in mapping XML):
// - String = JSON array of exact Jason literal/rule source strings, sorted lexically.
// - Preserve namespace, strong negation, arguments, annotations and source qualifiers.
// - A predicate-specific view selects actual stored literals by namespace/name/arity.
// - [] means a known empty extension ONLY with complete player/cut coverage.
// - An unavailable/incomplete view is undefined, not []/false/an invented default.
// - A query result, plan variable or event is not automatically a stored belief.
// - joined/2 is a compatibility rule over joinedWsp/3; do not materialize its
//   inferred answers by pretending they were stored belief literals.
// - oblUnfulfilled/1 is event/lifecycle evidence; no persistent belief is assumed.
// - The shared BB may contain several schemes/artifacts (a1 and a2); keep the
//   full tuple/annotations. Do not collapse task/winner/best_bid to one scalar.
// - Native OCL does not parse these JSON views: predicates requiring typed belief
//   access need an explicitly declared, generic typed observer binding.

csl v4.0 AuctionState {
    orgContext AuctionOrg {
        orgContext auctionGroup {
            role auction_capabilities {
                // Entire observed BB; rules stay explicitly distinguishable from facts.
                attribute beliefBase : String optional mutable;
                // CArtAgO workspace membership percept: joinedWsp/3.
                attribute belief_joinedWsp : String optional mutable;
                // Agent-artifact focus relation: focusing/6.
                attribute belief_focusing : String optional mutable;
                // Scheme/goal/argument-name/value relation: goalArgument/4.
                attribute belief_goalArgument : String optional mutable;
                // Agent/role/group relation as believed by this player: play/3.
                attribute belief_play : String optional mutable;
                // Artifact-qualified percept extensions, not authoritative Artifact data.
                attribute belief_running : String optional mutable;
                attribute belief_task : String optional mutable;
                attribute belief_best_bid : String optional mutable;
                attribute belief_winner : String optional mutable;
            }

            role auctioneer specializes auction_capabilities;
            role participant specializes auction_capabilities;

            // Diagram containment: group coordinates Auction state. This is model
            // scope, not physical CArtAgO ownership or a disposal cascade.
            entity Auction {
                attribute id : String required;
                attribute running : Boolean required mutable default false;
                attribute task : String required mutable default 'no_task';
                // Read actual finite Double.MAX_VALUE; never replace it by zero.
                attribute best_bid : Real required mutable;
                attribute winner : String required mutable default 'no_winner';
                // Persistent Java field, NOT an observable property.
                attribute currentWinner : String required mutable default 'no_winner';
            }
        }
    }

    // Count observed specialized role occurrences, not ASL program declarations
    // or mission commitments. Violation is evaluated, not filtered out by mapping.
    context auctionGroup inv AuctioneerPopulation:
        self.auctioneer->size() = 1;
    context auctionGroup inv ParticipantPopulation:
        self.participant->size() <= 300;
}

rules.iStarSource:
// Canonical rationale: auction_istar_final_fixed.drawio, with the user's explicit
// correction that Auctioneer and Participant specialize auction_capabilities.
// Diagram edge labels define is-a; stale dependencyLeg metadata on those two
// graphical edges does not create additional goal Dependencies.
//
// In-body is-a is intentional: the existing original model builder preserves it,
// whereas its top-level is-a grammar alternative is not built into the model.
// Descriptions are comments because the original runtime model drops description.
// Auction is a collective organizational viewpoint. The DSL's agent declaration
// is its concrete notation; it is NOT another running JaCaMo agent or CSL Auction.
//
// MODEL/RUNTIME BINDING CONTRACT (data in case mapping XML, never Java constants):
// Auctioneer -> CSL auctioneer; Participant -> CSL participant;
// auction_capabilities -> CSL auction_capabilities (same-instance specialization).
// The base capability role is not an independently adopted MOISE role.
// self -> exact Auction resolved from scheme Id + workspace/artifact incarnation.
// service -> the actual start argument; step -> current player/goal/step invocation.
// Role belief attributes remain epistemic views, never Artifact/world predicates.
// D_bid uses ANY over this scheme's committed Participant occurrences, nonempty,
// matching the latest diagram label. XML must declare this population/quantifier;
// it is not encoded by renaming a Task or by modifying the original recurrence.
// Contract AUCTION_ATTEMPT_AND_ACCEPTED_BID/3.0: Participant completion is an
// observed attempt/decision, including ONLY the XML-declared intentional .fail.
// Collective O_bid additionally requires a source-confirmed accepted bid.
// Administrative goalSatisfied(bid) alone satisfies neither condition.
// AND is outcome conjunction. MOISE sequence and deadlines are checked separately
// by the authored OCL/observer; AND does not assert execution order.
//
// EXACT DIAGRAM DELTA: A_decide_t1 is absent in the latest diagram. The ASL
// ?focusing(...) query still belongs to the observed decide-plan prefix and
// resolves the target Artifact before A_decide_t2; it is not a sixth Task here.
//
// COMPATIBILITY: original strict GoalModelValidator reports FOUR limitations.
// The diagram has unary AND refinement A_decide <- A_decide_t2; this validator
// requires at least two AND children. Do not invent a second Task to satisfy it.
// It also rejects the three Dependency
// endpoints A_start/A_decide/P_bid because they are refinement parents. Preserve
// these real diagram endpoints. A versioned derived-dependency profile is needed;
// do not detach endpoints or remove refinements just to pass legacy validation.
// Current live admission must also support IS_A before claiming execution of this
// updated model. Actor inheritance syntax alone is not evidence of runtime support.

istar AuctionGoals {
    agent Auction {
        // auction(Id, Service): all three organizational outcomes are necessary.
        goal O_root : Achieve
        // Dependency realization, not a raw MOISE administrative status flag.
        goal O_start : Achieve > O_root
        goal O_bid : Achieve > O_root
        goal O_bid_attempt : Achieve > O_bid
        // This source field changes from no_winner only on an accepted improving bid.
        // The first accepted bid improves the initial MAX_VALUE; no console inference.
        goal O_bid_accepted : Achieve > O_bid condition {[ self.currentWinner <> 'no_winner' ]}
        goal O_decide : Achieve > O_root
    }

    // Shared ASL capability abstraction; concrete belief-state attributes are in CSL.
    role auction_capabilities {
    }

    role Auctioneer {
        Auctioneer is-a auction_capabilities

        goal A_start : Achieve
        // A_start_t1: successful makeArtifact and focus in this invocation.
        task A_start_t1 > A_start
        pre {[ step.enabled ]}
        post {[ step.succeeded ]}

        // A_start_t2: successful source start(service), bound to exact Auction.
        task A_start_t2 > A_start
        pre {[ not self.running ]}
        post {[ self.running and self.task = service ]}

        goal A_decide : Achieve
        // A_decide_t2: source focusing query resolves Artifact, then stop succeeds.
        task A_decide_t2 > A_decide
        pre {[ self.running ]}
        post {[ not self.running ]}

        resource A_artifact
            > needed-by A_start_t2
            > needed-by A_decide_t2
    }

    role Participant {
        Participant is-a auction_capabilities

        goal P_bid : Achieve
        // P_bid_t1: successful lookupArtifact and focus in this invocation.
        task P_bid_t1 > P_bid
        pre {[ step.enabled ]}
        post {[ step.succeeded ]}

        // P_bid_t2: completion of the participation decision/attempt.
        // A successful non-improving bid and the explicitly declared simulated
        // decline (.fail at the verified source site) both complete this Task.
        // Other failures or absent evidence do not. This is not bid acceptance.
        task P_bid_t2 > P_bid
        pre {[ step.enabled and self.running ]}
        post {[ step.completed ]}

        resource P_artifact > needed-by P_bid_t2
    }

    depend Auction.O_start -> goal D_start -> Auctioneer.A_start
    depend Auction.O_decide -> goal D_decide -> Auctioneer.A_decide
    // ANY observed Participant attempt, AND the separate actual-accepted-bid leaf.
    depend Auction.O_bid_attempt -> goal D_bid -> Participant.P_bid
}
